-- supabase-migration-v15-seed.sql
-- Seeds all Library, Cinema, and Accessibility Resource items into the resources table.
-- Run this in Supabase SQL Editor AFTER running migrations v1-v14.
-- Safe to re-run: uses ON CONFLICT DO NOTHING (skips items that already exist).

-- ── Library items (47) ────────────────────────────────────────────────────────
ON CONFLICT (section, slug) WHERE slug IS NOT NULL DO NOTHING;

-- ── Cinema items (42) ────────────────────────────────────────────────────────
ON CONFLICT (section, slug) WHERE slug IS NOT NULL DO NOTHING;

-- ── Accessibility resource items (81) ─────────────────────────────────────────────
-- For accessibility resources, slug = url (matches resource_favorites table)
ON CONFLICT (section, slug) WHERE slug IS NOT NULL DO NOTHING;

-- Done. Total: 170 items seeded.