INSERT INTO resources (title, description, status, visibility, tags, category, section, slug, author, director, creator, year, url, item_type, is_free, how_to_access, is_essential, format_list, platform_list, has_ad, has_captions, duration_minutes, location_note, admin_notes) VALUES
('Skin, Tooth, and Bone: The Basis of Movement Is Our People', 'The foundational text of the Disability Justice framework — the 10 Principles that have shaped organizing, arts practice, and access work globally. Short, accessible, visually rich. Every accessibility training should begin here. Free PDF at sinsinvalid.org.', 'approved', 'public', ARRAY['Disabled Voice','Disability Justice','Free'], 'disability-justice', 'library', 'skin-tooth-and-bone', 'Sins Invalid', NULL, NULL, 2016, 'https://sinsinvalid.org/skin-tooth-and-bone', 'zine', true, NULL, true, ARRAY['PDF','Print'], NULL, false, false, NULL, NULL, NULL),
('Access Intimacy: The Missing Link', 'The essay that introduced the concept of "access intimacy" — the feeling when someone understands your access needs intuitively, without it being a burden or transaction. One of the most widely assigned pieces in the field. Free at Leaving Evidence.', 'approved', 'public', ARRAY['Disabled Voice','Disability Justice','Free'], 'disability-justice', 'library', 'access-intimacy-the-missing-link', 'Mia Mingus', NULL, NULL, 2011, 'https://leavingevidence.wordpress.com/2011/05/05/access-intimacy-the-missing-link/', 'essay', true, NULL, true, ARRAY['Web'], NULL, false, false, NULL, NULL, NULL),
('Leaving Evidence (Blog Archive)', 'Mia Mingus''s searchable blog archive — essays on access intimacy, transformative justice, disability and race, pod mapping, and access as love. One of the most important ongoing writing projects in the field. Freely available in full.', 'approved', 'public', ARRAY['Disabled Voice','Disability Justice','Free'], 'disability-justice', 'library', 'leaving-evidence-blog', 'Mia Mingus', NULL, NULL, 2010, 'https://leavingevidence.wordpress.com', 'blog', true, NULL, false, ARRAY['Web'], NULL, false, false, NULL, NULL, NULL),
('Disability Visibility: First-Person Stories from the Twenty-First Century', '37 essays by disabled writers across race, gender, sexuality, and diagnosis — one of the most widely read and accessible entry points to disability culture. Widely available at public libraries, on Bookshare (free for print-disabled individuals), and in paperback.', 'approved', 'public', ARRAY['Disabled Voice','Disability Justice','Anthology'], 'disability-justice', 'library', 'disability-visibility-anthology', 'Alice Wong (ed.)', NULL, NULL, 2020, NULL, 'anthology', false, 'Available at most public libraries, on Bookshare (free for print-disabled individuals at bookshare.org), and to purchase from Vintage Books ($18 paperback). Large print and audiobook editions exist.', true, NULL, NULL, false, false, NULL, NULL, NULL),
('Care Work: Dreaming Disability Justice', 'Essays on collective access, care webs, and disabled femme of color experience. One of the most practically useful and beautifully written books in this field — essential for anyone building access into organizations and events, not just into architecture.', 'approved', 'public', ARRAY['Disabled Voice','Disability Justice','Intersectionality'], 'disability-justice', 'library', 'care-work-dreaming-disability-justice', 'Leah Lakshmi Piepzna-Samarasinha', NULL, NULL, 2018, NULL, 'book', false, 'Available at many public libraries, on Bookshare (free for print-disabled individuals), and from Arsenal Pulp Press. Ebook and audiobook available.', true, NULL, NULL, false, false, NULL, NULL, NULL),
('The Future Is Disabled', 'Follow-up to Care Work — written during and after COVID. Explicitly addresses disabled people''s pandemic experience, collective access in crisis, and what disability justice looks like after a mass disabling event.', 'approved', 'public', ARRAY['Disabled Voice','Disability Justice'], 'disability-justice', 'library', 'the-future-is-disabled', 'Leah Lakshmi Piepzna-Samarasinha', NULL, NULL, 2022, NULL, 'book', false, 'Available from Arsenal Pulp Press, at libraries, and on Bookshare (free for print-disabled individuals).', false, NULL, NULL, false, false, NULL, NULL, NULL),
('Disability Visibility Project — Essays & Media', 'Alice Wong''s curated archive of disability media criticism, cultural commentary, and first-person essays — an ongoing collection of essential reading by disabled writers. Fully free online with transcripts.', 'approved', 'public', ARRAY['Disabled Voice','Free'], 'disability-justice', 'library', 'disability-visibility-project-essays', 'Alice Wong (curator)', NULL, NULL, 2014, 'https://disabilityvisibilityproject.com/essays', 'blog', true, NULL, false, ARRAY['Web'], NULL, false, false, NULL, NULL, NULL),
('The 10 Principles of Disability Justice', 'The concise statement of the 10 Disability Justice principles — intersectionality, leadership of most impacted, sustainability, cross-movement solidarity, and more. The framework that has shaped the field. Free at the Sins Invalid website.', 'approved', 'public', ARRAY['Disabled Voice','Disability Justice','Free'], 'disability-justice', 'library', 'sins-invalid-10-principles', 'Sins Invalid', NULL, NULL, 2015, 'https://www.sinsinvalid.org/disability-justice-primer', 'toolkit', true, NULL, true, ARRAY['Web'], NULL, false, false, NULL, NULL, NULL),
('Being Heumann: An Unrepentant Memoir of a Disability Rights Activist', 'Judy Heumann led the 504 Sit-In in 1977 — the longest occupation of a federal building in US history — and is arguably the most important disability rights activist in American history. Essential history through first-person narrative.', 'approved', 'public', ARRAY['Disabled Voice','Disability History'], 'disability-justice', 'library', 'being-heumann', 'Judith Heumann with Kristen Joiner', NULL, NULL, 2020, NULL, 'book', false, 'Available at most public libraries, on Bookshare (free for print-disabled), and from Beacon Press. Audiobook narrated by Heumann herself.', false, NULL, NULL, false, false, NULL, NULL, NULL),
('A Disability History of the United States', 'A sweeping historical narrative from precolonial America through the ADA and beyond — disability woven into the full history of the nation. Essential context for understanding how and why disability rights developed the way they did.', 'approved', 'public', ARRAY['Disability History'], 'disability-justice', 'library', 'disability-history-of-the-united-states', 'Kim Nielsen', NULL, NULL, 2012, NULL, 'book', false, 'Available at most public libraries and from Beacon Press. Widely used in undergraduate courses.', false, NULL, NULL, false, false, NULL, NULL, NULL),
('Unspeakable Conversations', 'A 2003 New York Times essay in which disability rights attorney Harriet McBryde Johnson debates philosopher Peter Singer on the value of disabled lives — and refuses to be either tragic or polite about it. A masterpiece of disability rights writing. May require a free NYT account or library card to access.', 'approved', 'public', ARRAY['Disabled Voice','Disability Justice'], 'first-person', 'library', 'unspeakable-conversations', 'Harriet McBryde Johnson', NULL, NULL, 2003, 'https://www.nytimes.com/2003/02/16/magazine/unspeakable-conversations.html', 'essay', true, NULL, true, ARRAY['Web'], NULL, false, false, NULL, NULL, NULL),
('Too Late to Die Young: Nearly True Tales from a Life', 'Brilliant, funny, fierce memoir by disability rights attorney Harriet McBryde Johnson. Her writing is among the best disability memoir in print — she refuses every tragic or inspirational frame. Widely available in libraries.', 'approved', 'public', ARRAY['Disabled Voice'], 'first-person', 'library', 'too-late-to-die-young', 'Harriet McBryde Johnson', NULL, NULL, 2006, NULL, 'book', false, 'Available at many public libraries and from Picador (now out of print in hardcover; used copies widely available). Check Bookshare for accessible formats.', false, NULL, NULL, false, false, NULL, NULL, NULL),
('Haben: The DeafBlind Woman Who Conquered Harvard Law', 'DeafBlind activist and lawyer Haben Girma''s memoir makes assistive technology and disability rights law concrete and human. One of the most accessible entry points to disability memoir for general audiences.', 'approved', 'public', ARRAY['Disabled Voice','Deaf Culture'], 'first-person', 'library', 'haben-the-deafblind-woman', 'Haben Girma', NULL, NULL, 2019, NULL, 'book', false, 'Available at most public libraries, on Bookshare (free for print-disabled), and from Twelve Books. Audiobook available.', false, NULL, NULL, false, false, NULL, NULL, NULL),
('Year of the Tiger: An Activist''s Life', 'Alice Wong''s memoir — experimental in form, told through fragments, photos, and essays. An honest account of disabled Asian American activist life: the labor, the joy, the exhaustion, the community. A model for what disability writing can look like when it refuses linear narrative.', 'approved', 'public', ARRAY['Disabled Voice','Disability Justice','Intersectionality'], 'first-person', 'library', 'year-of-the-tiger', 'Alice Wong', NULL, NULL, 2022, NULL, 'book', false, 'Available at many public libraries, on Bookshare, and from Vintage Books.', false, NULL, NULL, false, false, NULL, NULL, NULL),
('Brilliant Imperfection: Grappling with Cure', 'Essential on the politics of cure and the intersection of trans and disability experience. Clare writes at the edge of what disability theory and disability memoir can do — beautifully.', 'approved', 'public', ARRAY['Disabled Voice','Crip Theory','Intersectionality'], 'first-person', 'library', 'brilliant-imperfection', 'Eli Clare', NULL, NULL, 2017, NULL, 'book', false, 'Available at many public libraries and from Duke University Press. Audiobook available.', false, NULL, NULL, false, false, NULL, NULL, NULL),
('Feminist, Queer, Crip', 'The most readable and rigorous intersection of feminist, queer, and disability politics. Essential on "curative time" — the assumption that disabled people''s futures require cure rather than accommodation. Widely used in graduate courses worldwide.', 'approved', 'public', ARRAY['Crip Theory','Intersectionality'], 'crip-theory', 'library', 'feminist-queer-crip', 'Alison Kafer', NULL, NULL, 2013, NULL, 'book', false, 'Available at most academic and many public libraries, and from Indiana University Press. A standard text for graduate disability studies courses.', true, NULL, NULL, false, false, NULL, NULL, NULL),
('Crip Theory: Cultural Signs of Queerness and Disability', 'The book that named the field. McRuer argues that compulsory able-bodiedness and compulsory heterosexuality are structurally related — and that crip and queer resistance share common ground. Dense but essential.', 'approved', 'public', ARRAY['Crip Theory'], 'crip-theory', 'library', 'crip-theory-mcRuer', 'Robert McRuer', NULL, NULL, 2006, NULL, 'book', false, 'Available at most academic libraries and from NYU Press.', false, NULL, NULL, false, false, NULL, NULL, NULL),
('Disability Theory', 'A clear and rigorous introduction to disability as an academic field — one of the most accessible entry points into disability studies theory. Covers the medical model, social model, and minority model; engages with identity politics, aesthetics, and embodiment.', 'approved', 'public', ARRAY['Crip Theory','Disability Studies'], 'crip-theory', 'library', 'disability-theory-siebers', 'Tobin Siebers', NULL, NULL, 2008, NULL, 'book', false, 'Available at most academic libraries and from University of Michigan Press.', false, NULL, NULL, false, false, NULL, NULL, NULL),
('Disability Studies Quarterly — Full Archive', 'The most important open-access peer-reviewed journal in disability studies — published since 1982, freely available online in full. Covers arts, culture, media, law, and history. Searchable archive is one of the best free research resources in the field.', 'approved', 'public', ARRAY['Open Access','Free','Academic'], 'crip-theory', 'library', 'disability-studies-quarterly', 'Society for Disability Studies', NULL, NULL, 1982, 'https://dsq-sds.org', 'journal', true, NULL, true, ARRAY['Web'], NULL, false, false, NULL, NULL, NULL),
('Deaf in America: Voices from a Culture', 'The foundational text of Deaf cultural studies — written from inside the culture by Deaf scholars. Essential first read for any hearing practitioner working with Deaf artists or audiences. Establishes the cultural/linguistic model of Deafness.', 'approved', 'public', ARRAY['Deaf Culture','Disabled Voice'], 'deaf-culture', 'library', 'deaf-in-america', 'Carol Padden & Tom Humphries', NULL, NULL, 1988, NULL, 'book', false, 'Available at most academic libraries and many public libraries. Published by Harvard University Press.', true, NULL, NULL, false, false, NULL, NULL, NULL),
('National Association of the Deaf — Position Papers', 'Free position papers from the leading US Deaf advocacy organization — on cochlear implants, ASL recognition, captioning quality, Deaf civil rights, and more. This is what the Deaf community itself says about these issues — not what hearing organizations say about Deaf people.', 'approved', 'public', ARRAY['Deaf Culture','Disabled Voice','Free'], 'deaf-culture', 'library', 'nad-position-papers', 'National Association of the Deaf (NAD)', NULL, NULL, NULL, 'https://www.nad.org/resources/technology/telephone-and-relay-services/', 'toolkit', true, NULL, false, ARRAY['Web'], NULL, false, false, NULL, NULL, NULL),
('Through Deaf Eyes: A Documentary History of Deaf America', 'The companion volume to the PBS documentary — a documentary history of Deaf America covering education, arts, technology, and community. Produced alongside the 2007 PBS series.', 'approved', 'public', ARRAY['Deaf Culture'], 'deaf-culture', 'library', 'through-deaf-eyes-companion', 'Brenda Jo Brueggemann (ed.)', NULL, NULL, 2007, NULL, 'anthology', false, 'Available at most academic libraries and from Gallaudet University Press. The PBS documentary is free to watch at pbs.org.', false, NULL, NULL, false, false, NULL, NULL, NULL),
('True Biz', 'Named best book of 2022 by Publisher''s Weekly, Washington Post, NPR, and Booklist. Nović is Deaf herself. Set at a residential school for the Deaf, it''s practically a primer on Deaf culture, ASL, language deprivation, and cochlear implant politics — wrapped in a brilliant, character-driven novel.', 'approved', 'public', ARRAY['Deaf Culture','Disabled Voice'], 'deaf-culture', 'library', 'true-biz', 'Sara Nović', NULL, NULL, 2022, NULL, 'book', false, 'Available at most public libraries, on Bookshare (free for print-disabled), and from Random House. Audiobook available.', true, NULL, NULL, false, false, NULL, NULL, NULL),
('Bodies in Commotion: Disability and Performance', 'The essential academic anthology on disability in theater, dance, and performance art. Essays from performers, scholars, and critics — covering crip aesthetics, access as artistic practice, and the politics of the disabled body on stage. Standard text for graduate performance studies.', 'approved', 'public', ARRAY['Disability Arts','Performance'], 'theater-performance', 'library', 'bodies-in-commotion', 'Carrie Sandahl & Philip Auslander (eds.)', NULL, NULL, 2005, NULL, 'anthology', false, 'Available at most academic libraries and from University of Michigan Press.', true, NULL, NULL, false, false, NULL, NULL, NULL),
('Disability Culture and Community Performance', 'Petra Kuppers'' rigorous and generous book on community performance with and by disabled people — moving between theory and practice, international and community contexts. Essential for anyone working in disability arts at the community level.', 'approved', 'public', ARRAY['Disability Arts','Performance'], 'theater-performance', 'library', 'disability-culture-community-performance', 'Petra Kuppers', NULL, NULL, 2011, NULL, 'book', false, 'Available at academic libraries and from Palgrave Macmillan.', false, NULL, NULL, false, false, NULL, NULL, NULL),
('HowlRound — Disability & Accessibility Archive', 'Free, searchable archive of essays, articles, and recorded conversations on disability aesthetics, accessibility in theater, and disabled theater artists. Published continuously; globally accessible; one of the best ongoing free resources for disability in theater.', 'approved', 'public', ARRAY['Disability Arts','Theater','Free'], 'theater-performance', 'library', 'howlround-disability-archive', 'HowlRound Theatre Commons', NULL, NULL, NULL, 'https://howlround.com/tags/disability-and-accessibility', 'blog', true, NULL, false, ARRAY['Web'], NULL, false, false, NULL, NULL, NULL),
('More Than Meets the Eye: What Blindness Brings to Art', 'Rigorous, accessible, and beautiful — Kleege argues that audio description is not a neutral transcription but a creative act that reflects the describer''s assumptions, aesthetics, and values. Essential for anyone working on AD as artistic practice, not just compliance.', 'approved', 'public', ARRAY['Disabled Voice','Audio Description'], 'audio-description', 'library', 'more-than-meets-the-eye', 'Georgina Kleege', NULL, NULL, 2018, NULL, 'book', false, 'Available at many academic libraries and from Oxford University Press.', true, NULL, NULL, false, false, NULL, NULL, NULL),
('ADLAB International Guidelines for Audio Description', 'The most comprehensive AD guidelines available — covering theory, methodology, and practical guidance across media formats. EU-funded; free PDF. The most widely cited international AD standard and the place to start for understanding the full scope of the practice.', 'approved', 'public', ARRAY['Audio Description','Free','Open Access'], 'audio-description', 'library', 'adlab-international-guidelines', 'ADLAB Project (EU-funded consortium)', NULL, NULL, 2014, 'https://www.adlabproject.eu/Docs/adlab%20book/', 'standard', true, NULL, true, ARRAY['PDF'], NULL, false, false, NULL, NULL, NULL),
('DCMP Audio Description Tip Sheet', 'One-page free guide covering core AD principles: objective language, present tense, visual identity description including race and disability. A perfect starting handout for workshops or AD training. Free from the federally-funded DCMP.', 'approved', 'public', ARRAY['Audio Description','Free'], 'audio-description', 'library', 'dcmp-audio-description-tip-sheet', 'Described and Captioned Media Program', NULL, NULL, NULL, 'https://dcmp.org/learn/227-audio-description-tip-sheet', 'toolkit', true, NULL, false, ARRAY['PDF','Web'], NULL, false, false, NULL, NULL, NULL),
('The Visual Made Verbal: A Comprehensive Training Manual and Guide to the History and Applications of Audio Description', 'The professional training manual for audio description in the US — written by one of the field''s veteran practitioners and former director of the American Council of the Blind''s Audio Description Project. The standard reference for AD training programs.', 'approved', 'public', ARRAY['Audio Description'], 'audio-description', 'library', 'the-visual-made-verbal', 'Joel Snyder', NULL, NULL, 2014, NULL, 'book', false, 'Available from the American Council of the Blind and through audio description training programs. Check with ACB at adp.acb.org for current availability.', false, NULL, NULL, false, false, NULL, NULL, NULL),
('DCMP Captioning Key', 'The most detailed and widely-used quality standard for captions in educational media — and broadly applied across the industry. Covers accuracy, placement, speaker identification, timing, and sound effects. Free from the federally-funded DCMP. The US captioner''s primary reference.', 'approved', 'public', ARRAY['Captioning','Free','Standard'], 'captioning', 'library', 'dcmp-captioning-key', 'Described and Captioned Media Program', NULL, NULL, NULL, 'https://dcmp.org/learn/captioningkey', 'standard', true, NULL, true, ARRAY['Web'], NULL, false, false, NULL, NULL, NULL),
('Caption with Intention — Open-Source Design System', 'The defining resource on expressive/creative captioning — developed with the Deaf community, recognized by the Academy of Motion Picture Arts and Sciences. Explores style, color, animation, and personality in captions beyond compliance defaults. Free to download: includes full design system PDF and After Effects project files.', 'approved', 'public', ARRAY['Captioning','Deaf Culture','Free','Open Access'], 'captioning', 'library', 'caption-with-intention', 'Caption with Intention Project', NULL, NULL, 2023, 'https://captionwithintention.org', 'standard', true, NULL, true, ARRAY['PDF','Web'], NULL, false, false, NULL, NULL, NULL),
('Netflix Timed Text Style Guide', 'Publicly available guide required for all Netflix content — and one of the most detailed practical industry references for anyone producing captions, even for non-Netflix projects. Covers accuracy, timing, speaker IDs, formatting, and platform-specific requirements. Free to read.', 'approved', 'public', ARRAY['Captioning','Free','Industry Standard'], 'captioning', 'library', 'netflix-timed-text-style-guide', 'Netflix', NULL, NULL, NULL, 'https://partnerhelp.netflixstudios.com/hc/en-us/articles/215758617', 'standard', true, NULL, false, ARRAY['Web'], NULL, false, false, NULL, NULL, NULL),
('Disability and the Media', 'The most comprehensive academic study of disability representation across media — television, film, digital platforms, and journalism. Covers both representation in content and accessibility of media delivery. Essential for anyone arguing for systemic change in media.', 'approved', 'public', ARRAY['Disability Arts','Media'], 'film-media', 'library', 'disability-and-the-media', 'Katie Ellis & Gerard Goggin', NULL, NULL, 2015, NULL, 'book', false, 'Available at most academic libraries and from Palgrave Macmillan.', true, NULL, NULL, false, false, NULL, NULL, NULL),
('The Cinema of Isolation: A History of Physical Disability in the Movies', 'The definitive historical survey of Hollywood disability tropes from silent film through the early 1990s — cataloguing every major disability film cliché and its cultural implications. Still the most comprehensive single historical account of disability in mainstream cinema.', 'approved', 'public', ARRAY['Film','Disability History'], 'film-media', 'library', 'cinema-of-isolation', 'Martin Norden', NULL, NULL, 1994, NULL, 'book', false, 'Available at academic libraries. Published by Rutgers University Press; used copies widely available.', false, NULL, NULL, false, false, NULL, NULL, NULL),
('Alt Text as Poetry — Workbook', 'A free workbook that reframes alt text as a creative and political practice — not just a technical requirement. Includes exercises, principles, and examples from museums and artists. Changes how you think about image description entirely. Written by a blind curator and a disabled artist.', 'approved', 'public', ARRAY['Disabled Voice','Free','Open Access','Digital'], 'digital', 'library', 'alt-text-as-poetry', 'Bojana Coklyat & Shannon Finnegan', NULL, NULL, 2020, 'https://alt-text-as-poetry.net', 'workbook', true, NULL, true, ARRAY['Web','PDF'], NULL, false, false, NULL, NULL, NULL),
('Understanding WCAG 2.1 — W3C WAI', 'The authoritative "Understanding" documents for each WCAG success criterion — explaining why each requirement exists, what it means, and how to meet it. Essential for web developers, designers, and platform builders. Freely available from the W3C.', 'approved', 'public', ARRAY['Digital','WCAG','Free','Open Access'], 'digital', 'library', 'w3c-wai-understanding-wcag', 'W3C Web Accessibility Initiative', NULL, NULL, NULL, 'https://www.w3.org/WAI/WCAG21/Understanding/', 'standard', true, NULL, false, ARRAY['Web'], NULL, false, false, NULL, NULL, NULL),
('Inclusive Design Toolkit', 'Free framework introducing the "persona spectrum" model of permanent, temporary, and situational disability — a powerful reframe for designers. The key insight: designing for disability improves design for everyone. Free download.', 'approved', 'public', ARRAY['Digital','Inclusive Design','Free'], 'digital', 'library', 'microsoft-inclusive-design-toolkit', 'Microsoft Design', NULL, NULL, NULL, 'https://www.microsoft.com/design/inclusive', 'toolkit', true, NULL, false, ARRAY['PDF','Web'], NULL, false, false, NULL, NULL, NULL),
('Beauty is a Verb: The New Poetry of Disability', 'The most important anthology of disability poetry — ALA Notable Book in Poetry 2012. Brings together established and emerging disabled poets with essays on disability poetics. The title is a manifesto: beauty as practice, not state. If you want to understand disability as cultural identity and expressive tradition, not just as subject matter for nondisabled writers, start here.', 'approved', 'public', ARRAY['Disabled Voice','Disability Arts','Poetry'], 'crip-theory', 'library', 'beauty-is-a-verb', 'Sheila Black, Jennifer Bartlett & Michael Northen (eds.)', NULL, NULL, 2011, NULL, 'anthology', false, 'Available at many public and academic libraries and from Cinco Puntos Press. An essential addition to any disability arts collection.', true, NULL, NULL, false, false, NULL, NULL, NULL),
('Exile and Pride: Disability, Queerness, and Liberation', 'Eli Clare''s foundational essay collection — activist, memoirist, poet — on the embodied experience of being white, disabled, queer, and from rural poverty. Weaves together disability, class, gender, and environmental politics in a way that prefigured much of what disability justice would later name. Beautifully written and politically essential.', 'approved', 'public', ARRAY['Disabled Voice','Disability Justice','Intersectionality'], 'crip-theory', 'library', 'exile-and-pride', 'Eli Clare', NULL, NULL, 1999, NULL, 'book', false, 'Available at many academic libraries, on Bookshare (free for print-disabled), and from Duke University Press.', false, NULL, NULL, false, false, NULL, NULL, NULL),
('Bodyminds Reimagined: (Dis)ability, Race, and Gender in Black Women''s Speculative Fiction', 'A pivotal academic work examining how disability, race, and gender intersect in speculative fiction by Black women writers. Schalk''s "bodymind" framework rejects the mind/body split and grounds disability in race and gender simultaneously. Essential for understanding disability justice as it operates in creative and cultural production.', 'approved', 'public', ARRAY['Disabled Voice','Disability Studies','Intersectionality'], 'crip-theory', 'library', 'bodyminds-reimagined', 'Sami Schalk', NULL, NULL, 2018, NULL, 'book', false, 'Available at most academic libraries and from Duke University Press.', false, NULL, NULL, false, false, NULL, NULL, NULL),
('Wordgathering: A Journal of Disability Poetry and Literature', 'The only US journal dedicated solely to poetry and prose by disabled writers — published online, free, since 2007. A living archive of disability literature in all its forms: fierce, tender, comic, elegiac, formally experimental, politically exact. Quarterly; free at wordgathering.com.', 'approved', 'public', ARRAY['Disabled Voice','Disability Arts','Free','Open Access','Poetry'], 'crip-theory', 'library', 'wordgathering-journal', 'Michael Northen (founding editor)', NULL, NULL, NULL, 'https://wordgathering.com', 'journal', true, NULL, false, ARRAY['Web'], NULL, false, false, NULL, NULL, NULL),
('Staring: How We Look', 'Garland-Thomson''s exploration of staring as a cultural practice — who gets stared at, what it communicates, and what disabled people, freaks, and wonders do back to those who stare. Essential for understanding the visual politics of disability in public life, arts, and media.', 'approved', 'public', ARRAY['Disability Studies','Crip Theory'], 'film-media', 'library', 'staring-garland-thomson', 'Rosemarie Garland-Thomson', NULL, NULL, 2009, NULL, 'book', false, 'Available at most academic libraries and from Oxford University Press.', false, NULL, NULL, false, false, NULL, NULL, NULL),
('Disability Incarcerated: Imprisonment and Disability in the United States and Canada', 'The essential collection on the intersection of disability and carceral systems — examining how prisons, psychiatric institutions, and "special education" function as interconnected systems of confinement for disabled people, particularly disabled people of color.', 'approved', 'public', ARRAY['Disability Justice','Intersectionality'], 'disability-justice', 'library', 'disability-incarcerated', 'Liat Ben-Moshe, Chris Chapman & Allison C. Carey (eds.)', NULL, NULL, 2014, NULL, 'anthology', false, 'Available at most academic libraries and from Palgrave Macmillan.', false, NULL, NULL, false, false, NULL, NULL, NULL),
('The Disability Studies Reader', 'The standard comprehensive anthology used in graduate disability studies courses — now in its fifth edition. Covers all major theoretical approaches: social model, crip theory, feminist disability studies, postcolonial perspectives, and more. The shelf-building text for anyone new to the field.', 'approved', 'public', ARRAY['Disability Studies','Academic'], 'syllabi', 'library', 'disability-studies-reader', 'Lennard J. Davis (ed.)', NULL, NULL, 2017, NULL, 'anthology', false, 'Available at most academic libraries and from Routledge. Widely used in graduate courses; used copies of earlier editions are often much cheaper.', true, NULL, NULL, false, false, NULL, NULL, NULL),
('Autistic Self Advocacy Network — Free Toolkits & Guides', 'Free guides, policy briefs, and community toolkits from the leading US autistic-led advocacy organization — developed by autistic people. Includes guides on neurodivergent inclusion, sensory-friendly programming, and disability rights.', 'approved', 'public', ARRAY['Disabled Voice','Neurodivergent','Free'], 'syllabi', 'library', 'asan-autistic-community-toolkits', 'Autistic Self Advocacy Network (ASAN)', NULL, NULL, NULL, 'https://autisticadvocacy.org/resources/', 'toolkit', true, NULL, false, ARRAY['PDF','Web'], NULL, false, false, NULL, NULL, NULL),
('Journal of Literary & Cultural Disability Studies', 'Peer-reviewed academic journal covering disability in literature, film, and cultural production — arts and humanities focused. High quality; essential for research on disability in fiction, theater, and media.', 'approved', 'public', ARRAY['Disability Studies','Disability Arts','Academic'], 'syllabi', 'library', 'journal-literary-cultural-disability-studies', 'Liverpool University Press', NULL, NULL, NULL, 'https://liverpooluniversitypress.co.uk/journals/id/28', 'journal', false, 'Available through most academic library journal subscriptions. Some articles available through institutional repositories.', false, NULL, NULL, false, false, NULL, NULL, NULL)
INSERT INTO resources (title, description, status, visibility, tags, category, section, slug, author, director, creator, year, url, item_type, is_free, how_to_access, is_essential, format_list, platform_list, has_ad, has_captions, duration_minutes, location_note, admin_notes) VALUES
('Crip Camp: A Disability Revolution', 'The documentary that changed everything for a generation of disability rights awareness. Starting at Camp Jened — a scrappy camp for disabled teens in the Catskills — it follows the activists who became the architects of the disability rights movement, including Judy Heumann and the 1977 San Francisco 504 Sit-In. Executive produced by Barack and Michelle Obama. Oscar-nominated. An absolute must-watch.', 'approved', 'public', ARRAY['Disabled Voice','Disability History','Disability Justice'], 'documentaries', 'cinema', 'crip-camp', NULL, 'James LeBrecht & Nicole Newnham', NULL, 2020, NULL, 'documentary', false, 'Available on Netflix (subscription required). Check your local public library — many offer free access to streaming services through Kanopy or similar programs.', true, NULL, ARRAY['Netflix'], true, true, 108, NULL, NULL),
('Lives Worth Living', 'The PBS documentary tracing the history of the American disability rights movement from the 1940s through the passage of the ADA in 1990. Features first-person testimony from key organizers including Judy Heumann, Ed Roberts, and others who led the fight. Essential context for understanding how and why the ADA exists — told by the people who built it. Free to stream through PBS.', 'approved', 'public', ARRAY['Disability History','Disabled Voice','Free'], 'documentaries', 'cinema', 'lives-worth-living', NULL, 'Eric Neudel', NULL, 2011, 'https://www.pbs.org/independentlens/documentaries/lives-worth-living/', 'documentary', true, NULL, true, NULL, ARRAY['PBS'], false, true, 56, NULL, NULL),
('Through Deaf Eyes', 'A sweeping two-hour PBS documentary on 200 years of Deaf American history and culture — from the founding of the American School for the Deaf in 1817 through Deaf President Now at Gallaudet in 1988 and beyond. Narrated by deaf and hard of hearing people; structured as cultural history, not as a medical story.', 'approved', 'public', ARRAY['Deaf Culture','Disability History'], 'documentaries', 'cinema', 'through-deaf-eyes', NULL, 'Lawrence Hott & Diane Garey', NULL, 2007, NULL, 'documentary', false, 'Check PBS.org for current free availability. Available for borrowing through many public libraries; also available from Gallaudet University Press.', false, NULL, ARRAY['PBS','Library'], false, true, 120, NULL, NULL),
('Sound and Fury', 'An Oscar-nominated documentary following a Deaf family in which two brothers must each decide whether to give their young children cochlear implants. One of the most morally complex and culturally important documentaries in Deaf history. Required viewing before forming opinions about cochlear implants.', 'approved', 'public', ARRAY['Deaf Culture','Disabled Voice'], 'documentaries', 'cinema', 'sound-and-fury', NULL, 'Josh Aronson', NULL, 2000, NULL, 'documentary', false, 'Available to rent or purchase on Amazon, Apple TV, and similar platforms. Many public libraries own the DVD or a digital lending copy — check Kanopy.', true, NULL, ARRAY['Rent/Buy','Library'], false, true, 80, NULL, NULL),
('Sins Invalid: An Unashamed Claim to Beauty', 'Documentary capturing the live performance event that has defined disability justice arts for two decades. Sins Invalid is a disability justice performance project centering disabled artists of color, queer and trans disabled artists, and the full, complex spectrum of disabled embodiment. This is what access-centered art looks and sounds like in practice.', 'approved', 'public', ARRAY['Disabled Voice','Disability Justice','Performance'], 'documentaries', 'cinema', 'sins-invalid-unashamed-claim', NULL, 'Sins Invalid', NULL, 2016, NULL, 'documentary', false, 'Available to rent through Vimeo On Demand at vimeo.com/sinsinvalid.', true, NULL, ARRAY['Vimeo','Rent/Buy'], false, false, 72, NULL, NULL),
('Intelligent Lives', 'Dan Habib''s documentary on intellectual disability, inclusion, and self-determination — featuring three young adults: Micah Fialka-Feldman, Naieer Shaheed, and Naomi Moncrieffe. Narrated by Chris Cooper. Challenges the assumption that intellectual disability defines limits on a person''s life.', 'approved', 'public', ARRAY['Disability History','Disabled Voice','Disability Justice'], 'documentaries', 'cinema', 'intelligent-lives', NULL, 'Dan Habib', NULL, 2018, NULL, 'documentary', false, 'Available on Kanopy (free with library card at many public libraries). Also available on Vimeo On Demand.', true, NULL, ARRAY['Vimeo','Kanopy','Library'], false, true, 72, NULL, NULL),
('Murderball', 'An Oscar-nominated documentary about quadriplegic wheelchair rugby. Remarkable for refusing every standard trope about disability: there is no inspirational arc, no cure narrative, no tragedy. The athletes are portrayed as fierce, competitive, funny, and sexual — fully human.', 'approved', 'public', ARRAY['Disability Representation'], 'documentaries', 'cinema', 'murderball', NULL, 'Henry Alex Rubin & Dana Adam Shapiro', NULL, 2005, NULL, 'documentary', false, 'Available to rent or purchase on digital platforms. Available on DVD through many public and academic libraries.', false, NULL, ARRAY['Rent/Buy','Library'], false, true, 88, NULL, NULL),
('Notes on Blindness', 'Based on the audio diaries of theologian John Hull, who lost his sight in 1983. The film recreates his recordings with actors and extraordinary sound design, rendering the interior experience of blindness rather than an exterior view of it. Won multiple awards at Sundance and BAFTA.', 'approved', 'public', ARRAY['Disabled Voice','Disability Representation'], 'documentaries', 'cinema', 'notes-on-blindness', NULL, 'Peter Middleton & James Spinney', NULL, 2016, NULL, 'documentary', false, 'Available on MUBI and to rent/purchase on streaming platforms. DVD available at many libraries.', true, NULL, ARRAY['Mubi','Rent/Buy','Library'], true, true, 90, NULL, NULL),
('Far from the Tree', 'Based on Andrew Solomon''s landmark book — a documentary following parents of children who are different from them in profound ways: a Deaf child, a child with Down syndrome, a child with autism, a child born with dwarfism. Beautifully made and genuinely complex.', 'approved', 'public', ARRAY['Deaf Culture','Disability Identity'], 'documentaries', 'cinema', 'far-from-the-tree', NULL, 'Rachel Dretzin', NULL, 2017, NULL, 'documentary', false, 'Available on Hulu and to rent or purchase on streaming platforms.', false, NULL, ARRAY['Hulu','Rent/Buy'], false, true, 93, NULL, NULL),
('When I Walk', 'Filmmaker Jason DaSilva began documenting his own MS diagnosis at age 25 and continued filming for five years as his disability progressed. The resulting documentary is a frank, intimate, and formally inventive portrait of living with progressive disability.', 'approved', 'public', ARRAY['Disabled Voice','Disability Representation'], 'documentaries', 'cinema', 'when-i-walk', NULL, 'Jason DaSilva', NULL, 2013, NULL, 'documentary', false, 'Available on Vimeo On Demand and at many public libraries.', false, NULL, ARRAY['Vimeo','Library'], false, true, 85, NULL, NULL),
('AXIS Dance Company — Free Video Archive', 'AXIS Dance Company (Oakland, CA) — one of the longest-running integrated dance companies in the world, integrating wheelchair users and standing dancers — posts full performances, excerpts, and process videos freely on YouTube. Their work doesn''t just "include" disabled dancers; the artistic vocabulary of integrated movement is the whole point.', 'approved', 'public', ARRAY['Disabled Voice','Disability Arts','Free','Dance'], 'performance', 'cinema', 'axis-dance-company-recordings', NULL, NULL, 'AXIS Dance Company', NULL, 'https://www.youtube.com/@axisdancecompany', 'performance-recording', true, NULL, true, NULL, ARRAY['YouTube'], false, true, NULL, NULL, NULL),
('Kinetic Light — Performance Films', 'Kinetic Light is a disability-led performance company whose work in dance, technology, and access has redefined what both of those terms mean. Their Audimance® platform lets audience members choose from multiple audio tracks during live performance. Many excerpts and full performances are freely available.', 'approved', 'public', ARRAY['Disabled Voice','Disability Arts','Free','Dance','Audio Description'], 'performance', 'cinema', 'kinetic-light-wired', NULL, NULL, 'Kinetic Light (Alice Sheppard & Laurel Lawson)', 2019, 'https://kineticlight.org/wired', 'performance-recording', true, NULL, false, NULL, ARRAY['Vimeo','Web'], false, false, NULL, NULL, NULL),
('Deaf West Theatre: Spring Awakening', 'The 2015 Deaf West production of Spring Awakening on Broadway — performed simultaneously in ASL and English, with deaf and hearing actors fully integrated — was a landmark in American theater. Multiple excerpts, Tony Award performances, and behind-the-scenes footage are free on YouTube.', 'approved', 'public', ARRAY['Deaf Culture','Disability Arts','Theater'], 'performance', 'cinema', 'deaf-west-spring-awakening', NULL, NULL, 'Deaf West Theatre', 2015, NULL, 'performance-recording', false, 'Full production recording not commercially available. Extensive excerpts and performances on YouTube — search "Deaf West Spring Awakening Tony Awards."', false, NULL, ARRAY['YouTube (excerpts)','Library'], false, false, NULL, NULL, NULL),
('Graeae Theatre Company — Archive & Recordings', 'Graeae is the UK''s leading disabled-led theater company — founded in 1980. Their productions integrate captioning, BSL, and audio description as theatrical language — not add-ons. Selected recordings and excerpts available free via their website and on YouTube.', 'approved', 'public', ARRAY['Disabled Voice','Disability Arts','Free','International'], 'performance', 'cinema', 'graeae-theatre-recordings', NULL, NULL, 'Graeae Theatre Company (UK)', NULL, 'https://graeae.org', 'performance-recording', true, NULL, false, NULL, ARRAY['YouTube','Web'], false, false, NULL, NULL, NULL),
('Disability Film Challenge — Annual Winners', 'Each year, the Easterseals Disability Film Challenge releases winning short films on YouTube — all made within a 55-hour filmmaking window, all featuring disabled talent in front of and behind the camera. The result is a growing free archive of authentic short disability filmmaking.', 'approved', 'public', ARRAY['Disabled Voice','Disability Arts','Free'], 'short-film', 'cinema', 'disability-film-challenge-winners', NULL, NULL, 'Easterseals Disability Film Challenge', NULL, 'https://www.youtube.com/@disabilityfilmchallenge', 'short-film', true, NULL, false, NULL, ARRAY['YouTube'], false, true, NULL, NULL, NULL),
('Disability Visibility Project — Film & Video Archive', 'Alice Wong''s Disability Visibility Project maintains a growing archive of short films, video essays, recorded readings, and multimedia pieces — all freely available, most captioned. Includes her own on-camera work, community-produced films, and curated media.', 'approved', 'public', ARRAY['Disabled Voice','Free'], 'short-film', 'cinema', 'disability-visibility-project-films', NULL, NULL, 'Disability Visibility Project (Alice Wong)', NULL, 'https://disabilityvisibilityproject.com/read-watch-listen/', 'short-film', true, NULL, false, NULL, ARRAY['Web','YouTube'], false, true, NULL, NULL, NULL),
('Superfest International Disability Film Festival — Online Archive', 'Superfest is the world''s longest-running disability film festival, and it makes selected past films available for free online streaming. Every film in the Superfest archive has been screened with open captions and audio description. The most accessible film festival archive in existence.', 'approved', 'public', ARRAY['Disabled Voice','Disability Arts','Free','International'], 'short-film', 'cinema', 'superfest-online-archive', NULL, NULL, 'Superfest (Berkeley/UCSF)', NULL, 'https://superfestfilm.com', 'short-film', true, NULL, false, NULL, ARRAY['Web'], true, true, NULL, NULL, NULL),
('DisabilityArts.TV — Online Film Platform (UK)', 'A free UK-based online platform dedicated to disability arts film and video — short films, documentation of live work, artist interviews, and experimental video art. Disability Arts Online is the leading UK platform for disability arts criticism and culture.', 'approved', 'public', ARRAY['Disabled Voice','Disability Arts','Free','International'], 'short-film', 'cinema', 'disabilityarts-tv', NULL, NULL, 'Disability Arts Online (UK)', NULL, 'https://disabilityartsonline.org.uk/disability-arts-film', 'short-film', true, NULL, false, NULL, ARRAY['Web'], false, true, NULL, NULL, NULL),
('Disability Visibility Project', 'The essential disability culture podcast. Alice Wong interviews disabled activists, artists, writers, musicians, and community organizers — centering voices that are rarely centered elsewhere. The archive spans hundreds of episodes across all disability communities. Transcripts provided for every episode.', 'approved', 'public', ARRAY['Disabled Voice','Disability Justice','Free'], 'podcasts', 'cinema', 'disability-visibility-project-podcast', NULL, NULL, 'Alice Wong', NULL, 'https://disabilityvisibilityproject.com/podcasts/', 'podcast', true, NULL, true, NULL, ARRAY['Podcast','Web'], false, true, NULL, NULL, NULL),
('Reid My Mind Radio', 'Thomas Reid — blind audio describer, narrator, and storyteller — produces one of the most artfully crafted disability podcasts. Reid My Mind Radio covers blindness, audio description craft, disability culture, and Black disability experience. His AD training episodes are among the best free resources for aspiring audio describers. Full transcripts available.', 'approved', 'public', ARRAY['Disabled Voice','Audio Description','Free'], 'podcasts', 'cinema', 'reid-my-mind-radio', NULL, NULL, 'Thomas Reid', NULL, 'https://reidmymind.com', 'podcast', true, NULL, true, NULL, ARRAY['Podcast','Web'], false, false, NULL, NULL, NULL),
('The Accessible Stall', 'A candid, often funny, and always sharp podcast about disability culture, identity, and the everyday experience of being disabled in America. Emily Ladau and Kyle Khachadurian cover everything from ableism in pop culture to accessibility in travel to disability pride politics.', 'approved', 'public', ARRAY['Disabled Voice','Free'], 'podcasts', 'cinema', 'the-accessible-stall', NULL, NULL, 'Emily Ladau & Kyle Khachadurian', NULL, 'https://www.theaccessiblestall.com', 'podcast', true, NULL, false, NULL, ARRAY['Podcast','Web'], false, false, NULL, NULL, NULL),
('Disability After Dark', 'Andrew Gurza''s long-running podcast at the explicit intersection of disability and queerness — sexuality, dating, intimacy, and identity as a disabled gay man. Goes where very few disability podcasts go: the sexual lives, desires, and experiences of disabled people as worthy of celebration.', 'approved', 'public', ARRAY['Disabled Voice','Free','LGBTQ+'], 'podcasts', 'cinema', 'disability-after-dark', NULL, NULL, 'Andrew Gurza', NULL, 'https://disabilityafterdark.com', 'podcast', true, NULL, false, NULL, ARRAY['Podcast','Web'], false, false, NULL, NULL, NULL),
('Krip-Hop Nation Radio & Podcast', 'Leroy F. Moore Jr. is the founder of Krip-Hop Nation — a platform and movement celebrating hip-hop artists with disabilities. Connects disability culture with hip-hop history, Black disability culture, and the stories of disabled musicians who are consistently erased from mainstream music history.', 'approved', 'public', ARRAY['Disabled Voice','Disability Justice','Free','Music'], 'podcasts', 'cinema', 'krip-hop-nation-podcast', NULL, NULL, 'Leroy F. Moore Jr.', NULL, 'https://kriphopnation.com', 'podcast', true, NULL, false, NULL, ARRAY['Podcast','Web'], false, false, NULL, NULL, NULL),
('The War on Wheels', 'Dominick Evans — disabled filmmaker and activist — hosts this podcast covering disability representation in media: film, TV, and social media. Episodes cover authentic casting, cripping up, disability tropes, and what it means to have creative control over your own story.', 'approved', 'public', ARRAY['Disabled Voice','Film','Representation','Free'], 'podcasts', 'cinema', 'the-war-on-wheels-podcast', NULL, NULL, 'Dominick Evans', NULL, 'https://dominickevans.com/the-war-on-wheels-podcast/', 'podcast', true, NULL, false, NULL, ARRAY['Podcast','Web'], false, false, NULL, NULL, NULL),
('Speechless', 'Three seasons (ABC, 2016–2019) of a sitcom centering JJ DiMeo — a teenager with cerebral palsy — played by Micah Fowler, who has cerebral palsy himself. Remarkable for using AAC as the actual comic mechanism. One of very few mainstream sitcoms to cast a disabled actor in the disabled lead role.', 'approved', 'public', ARRAY['Disabled Voice','Disability Representation'], 'series-tv', 'cinema', 'speechless', NULL, NULL, 'Scott Silveri', 2016, NULL, 'series', false, 'Available on Hulu (subscription). May be available through your library''s digital lending service.', true, NULL, ARRAY['Hulu','Disney+','Rent/Buy'], false, true, NULL, NULL, NULL),
('Deaf U', 'A Netflix docu-series following Deaf and hard of hearing students at Gallaudet University in Washington, DC — the world''s only university designed for Deaf students. A genuine and rare window into Deaf campus life and the diversity of Deaf identity.', 'approved', 'public', ARRAY['Deaf Culture','Disabled Voice'], 'series-tv', 'cinema', 'deaf-u', NULL, NULL, 'Nyle DiMarco (exec. producer)', 2020, NULL, 'series', false, 'Available on Netflix (subscription required).', false, NULL, ARRAY['Netflix'], false, true, NULL, NULL, NULL),
('Special', 'Ryan O''Connell — a disabled, gay writer — created, wrote, and stars in this semi-autobiographical Netflix comedy about a young man with cerebral palsy navigating early adulthood, queerness, disability identity, and the decision of whether to disclose his disability. Two seasons. Sharp, funny, and genuinely self-aware about disability politics.', 'approved', 'public', ARRAY['Disabled Voice','LGBTQ+'], 'series-tv', 'cinema', 'special-netflix', NULL, NULL, 'Ryan O''Connell', 2019, NULL, 'series', false, 'Available on Netflix (subscription required).', true, NULL, ARRAY['Netflix'], false, true, NULL, NULL, NULL),
('The A Word', 'A BBC/Sky series following a family coming to understand that their young son is autistic. The British original is widely praised for its authentic portrayal of autistic experience and the complexity of family dynamics around late diagnosis. The writing around what autism means and doesn''t mean is unusually thoughtful for mainstream TV.', 'approved', 'public', ARRAY['Disability Representation','Neurodivergent'], 'series-tv', 'cinema', 'the-a-word', NULL, NULL, 'Peter Bowker (UK)', 2016, NULL, 'series', false, 'Available on Acorn TV and Peacock; also available to rent/purchase on streaming platforms.', false, NULL, ARRAY['Peacock','Acorn TV','Rent/Buy'], false, true, NULL, NULL, NULL),
('Children of a Lesser God', 'Marlee Matlin''s Oscar-winning performance as a deaf woman in a relationship with a hearing speech therapist. Complex — the film''s framing reflects its era, and its ending is contested. But Matlin''s performance, the centrality of ASL, and the frank depiction of Deaf-hearing power dynamics make it required viewing.', 'approved', 'public', ARRAY['Deaf Culture','Disability Representation'], 'narrative-film', 'cinema', 'children-of-a-lesser-god', NULL, 'Randa Haines', NULL, 1986, NULL, 'film', false, 'Available to rent or purchase on most digital streaming platforms. Available on DVD through many public libraries.', true, NULL, ARRAY['Rent/Buy','Library'], false, true, 119, NULL, NULL),
('The Diving Bell and the Butterfly', 'Based on Jean-Dominique Bauby''s memoir, written by blinking his left eye after a brainstem stroke. Schnabel puts the camera behind Bauby''s eye for the film''s first act, putting the viewer in locked-in consciousness in a way that''s unlike any other film.', 'approved', 'public', ARRAY['Disability Representation','International'], 'narrative-film', 'cinema', 'the-diving-bell-and-the-butterfly', NULL, 'Julian Schnabel', NULL, 2007, NULL, 'film', false, 'Available to rent or purchase on Amazon, Apple TV, and similar platforms. Available on DVD through many public libraries.', false, NULL, ARRAY['Rent/Buy','Library'], false, true, 112, NULL, NULL),
('Keep the Change', 'A love story between two autistic adults — played by autistic actors Brandon Polansky and Samantha Elisofon — who meet in a social skills program in New York City. One of the only mainstream narrative films in which autistic characters are played by autistic actors. Won the Audience Award at the Tribeca Film Festival.', 'approved', 'public', ARRAY['Disabled Voice','Disability Representation','Neurodivergent'], 'narrative-film', 'cinema', 'keep-the-change', NULL, 'Rachel Israel', NULL, 2017, NULL, 'film', false, 'Available to rent or purchase on Amazon, Apple TV, and similar platforms.', true, NULL, ARRAY['Rent/Buy'], false, false, 94, NULL, NULL),
('Sound of Metal', 'A heavy metal drummer loses his hearing rapidly and must reckon with what that loss means. Won the Academy Award for Sound and Film Editing. The sound design is transformative — the film lets you hear through the character''s changing ears.', 'approved', 'public', ARRAY['Deaf Culture','Disability Representation'], 'narrative-film', 'cinema', 'sound-of-metal', NULL, 'Darius Marder', NULL, 2019, NULL, 'film', false, 'Available on Amazon Prime Video (subscription) and to rent/purchase on other platforms.', false, NULL, ARRAY['Amazon Prime'], true, true, 130, NULL, NULL),
('CODA', 'Best Picture winner at the 2022 Academy Awards. A hearing child of Deaf adults navigates her hearing identity and her ambitions as a singer. Three of the four family roles played by Deaf or hard of hearing actors (Marlee Matlin, Troy Kotsur, Daniel Durant). Kotsur won Best Supporting Actor — the first Deaf actor to win that award.', 'approved', 'public', ARRAY['Deaf Culture','Disabled Voice'], 'narrative-film', 'cinema', 'coda-2021', NULL, 'Siân Heder', NULL, 2021, NULL, 'film', false, 'Available on Apple TV+ (subscription). Available to rent/purchase on other streaming platforms.', false, NULL, ARRAY['Apple TV+'], true, true, 112, NULL, NULL),
('I''m Not Your Inspiration, Thank You Very Much', 'The most-watched disability culture talk in TED history — Stella Young delivers the definitive 9-minute critique of inspiration porn: the objectification of disabled people for the emotional benefit of non-disabled people. She names the structure clearly, illustrates it with precision, and does it all with humor. Required viewing.', 'approved', 'public', ARRAY['Disabled Voice','Free'], 'talks-lectures', 'cinema', 'stella-young-not-your-inspiration', NULL, NULL, 'Stella Young', 2014, 'https://www.ted.com/talks/stella_young_i_m_not_your_inspiration_thank_you_very_much', 'talk', true, NULL, true, NULL, ARRAY['TED','YouTube'], false, true, 9, NULL, NULL),
('Haben Girma: How Accessibility Leads to Equality', 'DeafBlind disability rights lawyer Haben Girma makes the case that accessibility is not charity — it''s civil rights, and it creates opportunity for everyone. One of the most effective accessible talks about accessibility. Full transcript on TED.com.', 'approved', 'public', ARRAY['Disabled Voice','Free'], 'talks-lectures', 'cinema', 'haben-girma-accessibility-law', NULL, NULL, 'Haben Girma', 2018, 'https://www.ted.com/talks/haben_girma_how_accessibility_leads_to_equality', 'talk', true, NULL, false, NULL, ARRAY['TED'], false, true, 13, NULL, NULL),
('Our Fight for Disability Rights — and Why We''re Not Done Yet', 'Judith Heumann — architect of the 504 Sit-In, key drafter of the IDEA and ADA — delivers a full account of how she became an organizer and why the fight continues. Full transcript on TED.com.', 'approved', 'public', ARRAY['Disabled Voice','Disability History','Free'], 'talks-lectures', 'cinema', 'judy-heumann-disability-rights', NULL, NULL, 'Judith Heumann', 2016, 'https://www.ted.com/talks/judith_heumann_our_fight_for_disability_rights_and_why_we_re_not_done_yet', 'talk', true, NULL, false, NULL, ARRAY['TED'], false, true, 15, NULL, NULL),
('Alice Wong — Talks & Recorded Lectures', 'Alice Wong''s recorded talks — at conferences, universities, and festivals — are collected and linked through the Disability Visibility Project website. She speaks on disability identity, ableism in healthcare, disability media representation, and the labor of disabled activists.', 'approved', 'public', ARRAY['Disabled Voice','Disability Justice','Free'], 'talks-lectures', 'cinema', 'alice-wong-disability-visibility-talks', NULL, NULL, 'Alice Wong', NULL, 'https://disabilityvisibilityproject.com/read-watch-listen/', 'talk', true, NULL, false, NULL, ARRAY['Web','YouTube'], false, true, NULL, NULL, NULL),
('Thomas Reid — Audio Description Training Talks', 'Thomas Reid — blind narrator, audio describer, and host of Reid My Mind Radio — has delivered public talks and training sessions on audio description craft available free online. His talks on objectivity, identity description, and the aesthetics of description are among the most practically useful free resources for practicing audio describers.', 'approved', 'public', ARRAY['Disabled Voice','Audio Description','Free'], 'talks-lectures', 'cinema', 'thomas-reid-audio-description-demo', NULL, NULL, 'Thomas Reid', NULL, 'https://reidmymind.com', 'talk', true, NULL, false, NULL, ARRAY['YouTube','Web'], false, true, NULL, NULL, NULL),
('Joybubbles', 'A documentary portrait of Joe Engressia, born blind, who became one of the first phone phreaks. Made its world premiere at Sundance 2026, where it became the first film in Sundance history to be screened with open audio description. A landmark in disability arts accessibility.', 'approved', 'public', ARRAY['Disabled Voice','Disability Arts','Audio Description'], 'festival-recent', 'cinema', 'joybubbles-2026', NULL, 'Rachael J. Morrison', NULL, 2026, NULL, 'documentary', false, 'Currently in festival distribution following its Sundance 2026 premiere. Watch for streaming announcement.', false, NULL, ARRAY['Festival Circuit'], true, true, NULL, NULL, NULL),
('Disposable Humanity', 'Centerpiece film at ReelAbilities New York 2026. Investigates the Nazi Aktion T4 program — which systematically killed an estimated 200,000–300,000 disabled people beginning in 1939, before the broader Holocaust machinery was deployed.', 'approved', 'public', ARRAY['Disability History'], 'festival-recent', 'cinema', 'disposable-humanity-2026', NULL, 'Cameron S. Mitchell', NULL, 2026, NULL, 'documentary', false, 'Screened at ReelAbilities New York 2026. Watch for streaming and distribution announcements at reelabilities.org.', false, NULL, ARRAY['Festival Circuit'], false, false, NULL, NULL, NULL),
('VIKTOR — A Deaf Man in a War He Cannot Hear', 'Portrait of a Deaf Ukrainian man navigating the Russian invasion of Ukraine. Screened at ReelAbilities New York 2026. A powerful intersection of Deaf identity, war, and the particular experience of navigating conflict without hearing.', 'approved', 'public', ARRAY['Deaf Culture','Disabled Voice','International'], 'festival-recent', 'cinema', 'viktor-deaf-man-war-2026', NULL, 'Olivier Sarbila', NULL, 2026, NULL, 'documentary', false, 'Currently in festival distribution. Watch for streaming announcements at reelabilities.org.', false, NULL, ARRAY['Festival Circuit'], false, false, NULL, NULL, NULL),
('ReelAbilities Film Festival — Curated Archive', 'ReelAbilities — now in 20+ cities across the US — curates the best in disability-focused filmmaking each year and maintains an online archive of past programming. Their programming is the best single annual guide to what''s worth watching in disability cinema.', 'approved', 'public', ARRAY['Disability Arts','Free (selected)'], 'festival-recent', 'cinema', 'reelabilities-curated-series', NULL, NULL, 'ReelAbilities Film Festival', NULL, 'https://reelabilities.org', 'documentary', false, 'Visit reelabilities.org for current programming and links to films available for online streaming.', false, NULL, ARRAY['Web'], false, false, NULL, NULL, NULL)
INSERT INTO resources (title, description, status, visibility, tags, category, section, slug, author, director, creator, year, url, item_type, is_free, how_to_access, is_essential, format_list, platform_list, has_ad, has_captions, duration_minutes, location_note, admin_notes) VALUES
('UN Convention on the Rights of Persons with Disabilities (CRPD)', 'The foundational international disability rights instrument — entered into force 2008, 190 states parties. Article 30 explicitly requires access to cultural life including theater, film, and museums. Free PDF.', 'approved', 'public', ARRAY['FREE','Open Access'], 'law-policy', 'accessibility', 'https://www.un.org/disabilities/documents/convention/convoptprot-e.pdf', NULL, NULL, NULL, NULL, 'https://www.un.org/disabilities/documents/convention/convoptprot-e.pdf', 'standard', true, NULL, false, NULL, NULL, false, false, NULL, NULL, NULL),
('W3C Web Accessibility Initiative (WAI)', 'The authoritative free source for WCAG — the global de facto standard for digital accessibility. Includes WCAG 2.1 and 2.2 specifications, Understanding documents, and tutorials. Referenced in law in the US, EU, UK, Canada, and Australia.', 'approved', 'public', ARRAY['FREE','Open Access'], 'law-policy', 'accessibility', 'https://www.w3.org/WAI', NULL, NULL, NULL, NULL, 'https://www.w3.org/WAI', 'standard', true, NULL, false, NULL, NULL, false, false, NULL, NULL, NULL),
('ADA.gov', 'The authoritative free source for all Americans with Disabilities Act guidance. Focus on Title III (public accommodations — most relevant to arts venues). Includes DOJ web accessibility guidance and the 2024 final rule requiring WCAG 2.1 AA for state and local government websites.', 'approved', 'public', ARRAY['FREE'], 'law-policy', 'accessibility', 'https://www.ada.gov', NULL, NULL, NULL, NULL, 'https://www.ada.gov', 'standard', true, NULL, false, NULL, NULL, false, false, NULL, 'United States', NULL),
('ADA National Network', 'Ten regional centers (one per US region) offering free ADA training, webinars, detailed guides, and a live helpline: 1-800-949-4232. The most accessible entry point for arts organizations trying to understand their ADA obligations.', 'approved', 'public', ARRAY['FREE'], 'law-policy', 'accessibility', 'https://adata.org', NULL, NULL, NULL, NULL, 'https://adata.org', 'org', true, NULL, false, NULL, NULL, false, false, NULL, 'United States', NULL),
('FCC — Closed Captioning on Television', 'FCC guide to captioning requirements under the CVAA and the four FCC quality standards: accuracy, synchrony, completeness, and placement. Essential background for film, broadcast, and streaming accessibility work in the US.', 'approved', 'public', ARRAY['FREE'], 'law-policy', 'accessibility', 'https://www.fcc.gov/consumers/guides/closed-captioning-television', NULL, NULL, NULL, NULL, 'https://www.fcc.gov/consumers/guides/closed-captioning-television', 'standard', true, NULL, false, NULL, NULL, false, false, NULL, 'United States', NULL),
('National Endowment for the Arts — Accessibility', 'Free policy guidance, case studies, and vetted resource links for US arts organizations. Accessibility is increasingly required in NEA grant criteria — this is the place to understand what NEA expects and what they fund.', 'approved', 'public', ARRAY['FREE'], 'law-policy', 'accessibility', 'https://www.arts.gov/impact/accessibility', NULL, NULL, NULL, NULL, 'https://www.arts.gov/impact/accessibility', 'org', true, NULL, false, NULL, NULL, false, false, NULL, 'United States', NULL),
